            if SourceDocumentLine.FindSet() then
                repeat
                    ItemFound := false;
                    UOMResolved := false;

                    if EDocService."Resolve Unit Of Measure" then
                        UOMResolved := EDocImportHelper.ResolveUnitOfMeasureFromDataImport(EDocument, SourceDocumentLine)
