                        OnValidateBillToCustomerNoOnAfterConfirmed(Rec)
                    else
                        "Bill-to Customer No." := xRec."Bill-to Customer No.";
                end;

                GetCust("Bill-to Customer No.");

                SetBillToCustomerAddressFieldsFromCustomer(Cust);

