                ValidateSalesPersonOnContractHeader(Rec);

                CreateDim(
                  Database::"Salesperson/Purchaser", "Salesperson Code",
                  Database::Job, "Dimension from Job No.",
                  Database::Customer, "Bill-to Customer No.");
            end;
