                OnBeforeValidateBillToCustomerName(Rec, Customer);

                if SalesHeader.ShouldSearchForCustomerByName("Bill-to Customer No.") then
                    Validate("Bill-to Customer No.", Customer.GetCustNo("Bill-to Name"));
            end;
