                    if GetHideValidationDialog() or not GuiAllowed then
                        Confirmed := true
                    else
                        Confirmed := ConfirmManagement.GetResponse(StrSubstNo(ConfirmChangeQst, SellToCustomerTxt), false);
                    if Confirmed then begin
                        if "Sell-to Customer No." = '' then begin
                            Init();
