{
    Subtype = Test;
    TestType = Uncategorized;
    TestPermissions = Disabled;
    Access = Internal;

    var
        TempContractRenewalLine: Record "Sub. Contract Renewal Line" temporary;
        CustomerContract: Record "Customer Subscription Contract";
